-- Reference data: book library ('books' archive section) for every universe (generated).
-- Real titles, authors and years; original summaries. Idempotent.

-- Harry Potter: the book section replaces the old generic library (books 1-4 now live in 'books').
UPDATE public.universe_settings st
   SET features = (SELECT jsonb_agg(CASE WHEN f = '"library"'::jsonb THEN '"books"'::jsonb ELSE f END ORDER BY ord)
                     FROM jsonb_array_elements(st.features) WITH ORDINALITY AS t(f, ord))
  FROM public.universes u WHERE u.id = st.universe_id AND u.slug = 'harry-potter' AND st.features ? 'library';
DELETE FROM public.lore_entries l USING public.universes u
 WHERE u.id = l.universe_id AND u.slug = 'harry-potter' AND l.section = 'library'
   AND l.slug IN ('pedra-filosofal', 'camara-secreta', 'prisioneiro-de-azkaban', 'calice-de-fogo');
-- Every other universe gains the book section (after its archive sections).
UPDATE public.universe_settings SET features = features || '["books"]'::jsonb WHERE NOT features ? 'books';

UPDATE public.lore_entries l SET tags = ARRAY['oficial']::text[] FROM public.universes u WHERE u.id = l.universe_id AND u.slug = 'harry-potter' AND l.section = 'books' AND l.tags = '{}';
